{"file_path":"src/parse.js","content":"const CMP = new Set(['=', '<>', '<', '<=', '>', '>='])

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue
    }
    const two = s.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') { toks.push({ t: 'op', v: two }); i += 2; continue }
    if ('^*/+-=<>(),:'.includes(ch)) { toks.push({ t: 'op', v: ch }); i++; continue }
    return null
  }
  return toks
}

export function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return { ok: false }
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => peek() && peek().t === 'op' && peek().v === v
  const bad = () => { throw new Error('syntax') }

  function cmp() {
    let l = add()
    while (peek() && peek().t === 'op' && CMP.has(peek().v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { k: 'un', op, e: unary() }
    }
    return primary(false)
  }
  function primary(argPos) {
    const t = toks[p]
    if (!t) bad()
    if (t.t === 'num') { p++; return { k: 'num', v: t.v } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) bad()
      p++
      return e
    }
    if (t.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) bad()
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          bad()
        }
        return { k: 'call', name: t.v.toUpperCase(), args }
      }
      const up = t.v.toUpperCase()
      if (up === 'TRUE' || up === 'FALSE') return { k: 'bool', v: up === 'TRUE' }
      return { k: 'ref', name: t.v }
    }
    return bad()
  }
  function arg() {
    // a range directly as an argument
    const t = toks[p]
    if (t && t.t === 'word' && toks[p + 1] && toks[p + 1].t === 'op' && toks[p + 1].v === ':') {
      const u = toks[p + 2]
      if (!u || u.t !== 'word') bad()
      const after = toks[p + 3]
      if (after && after.t === 'op' && after.v === '(') bad()
      p += 3
      const node = { k: 'range', a: t.v, b: u.v }
      if (!(isOp(',') || isOp(')'))) bad()
      return node
    }
    return cmp()
  }

  try {
    const ast = cmp()
    if (p !== toks.length) return { ok: false }
    return { ok: true, ast }
  } catch {
    return { ok: false }
  }
}
"}

