    else if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) v = num(Number(s))
    else if (ERRORS.has(s)) v = err(s)
    else v = { t: 's', v: s }
    this.busy.delete(key)
    this.memo.set(key, v)
    return v
  }

  toNum(v) {
    if (v.t === 'n') return v
    if (v.t === 'b') return num(v.v ? 1 : 0)
    return err('#VALUE!')
  }

  fin(x) {
    return Number.isFinite(x) ? num(x) : err('#DIV/0!')
  }

  node(n) {
    switch (n.k) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'ref': {
        const a = parseAddress(n.name)
        return a ? this.cellValue(a.key) : err('#REF!')
